import Model from 'flarum/common/Model';
/** A member's all-time record (`who-said-it-players`; the id is the user's). */
export default class Player extends Model {
  totalScore = Model.attribute('totalScore');
  quizzes = Model.attribute('quizzes');
  correctTotal = Model.attribute('correctTotal');
  bestStreak = Model.attribute('bestStreak');
  streak = Model.attribute('streak');
  user = Model.hasOne('user');
}
flarum.reg.add('ernestdefoe-who-said-it', 'forum/models/Player', Player);